const BOARD_ID = 2131896795;

async function fetchPage(cursor) {
  const cursorPart = cursor ? `, cursor: "${cursor}"` : '';
  const query = `{ boards(ids: [${BOARD_ID}]) { items_page(limit: 500${cursorPart}) { cursor items { id name column_values { id text } } } } }`;
  const resp = await fetch('https://api.monday.com/v2', {
    method: 'POST',
    headers: { 'Authorization': MONDAY_TOKEN, 'Content-Type': 'application/json', 'API-Version': '2023-10' },
    body: JSON.stringify({ query })
  });
  return resp.json();
}

const page1 = await fetchPage(null);
const page1Data = page1.data?.boards?.[0]?.items_page || {};
const items1 = page1Data.items || [];
const cursor = page1Data.cursor;

let items2 = [];
if (cursor) {
  const page2 = await fetchPage(cursor);
  items2 = page2.data?.boards?.[0]?.items_page?.items || [];
}

return [{ json: { items: [...items1, ...items2] } }];

const items = $input.first().json.items || [];
const now = Date.now();
const MS_30_DAYS = 30 * 24 * 60 * 60 * 1000;
const MS_24_HOURS = 86400000;

const parseDate = (dateStr) => {
  if (!dateStr) return null;
  if (dateStr.includes('-') && dateStr.split('-')[0].length === 4) return new Date(dateStr);
  if (dateStr.includes('/')) {
    const [day, month, year] = dateStr.split('/');
    const y = year.length === 2 ? '20' + year : year;
    return new Date(`${y}-${month.padStart(2,'0')}-${day.padStart(2,'0')}`);
  }
  return null;
};

const orders = [];
for (const item of items) {
  const cols = {};
  (item.column_values || []).forEach(c => { cols[c.id] = (c.text || '').trim(); });

  const d = parseDate(cols['date__1']);
  if (!d || isNaN(d.getTime())) continue;
  const age = now - d.getTime();
  if (age > MS_30_DAYS) continue;
  if (age < MS_24_HOURS) continue;

  const trackingNumber = (cols['text__1'] || '').replace(/\s/g, '');
  if (!trackingNumber) continue;

  const phone = (cols['phone__1'] || '').replace(/[^0-9]/g, '');
  if (phone.length < 9) continue;

  if (item.name.match(/TEST/i)) continue;

  orders.push({ item_id: item.id, customer_name: item.name, tracking_number: trackingNumber, phone });
}

return orders.map(o => ({ json: o }));

const staticData = $getWorkflowStaticData('global');
const order = $('Parse & Filter Orders').item.json;
const tracking = order.tracking_number;

// [1] TIME: only send 09:00-20:00 Israel time (UTC+3)
const israelHour = (new Date().getUTCHours() + 3) % 24;
if (israelHour < 9 || israelHour >= 20) return [];

// Get XML text
const xmlStr = (() => {
  const r = $input.first().json;
  if (typeof r === 'string') return r;
  if (typeof r.data === 'string') return r.data;
  if (typeof r.body === 'string') return r.body;
  return JSON.stringify(r);
})();

const getTag = (str, tag) => {
  const m = str.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'i'));
  return m ? m[1].trim() : '';
};

const note = getTag(xmlStr, 'note');
if (note && (note.includes('error') || note.includes('Error'))) return [];

const shipStagesXml = getTag(xmlStr, 'ship_stages');
if (!shipStagesXml) return [];

const stageMatches = [...shipStagesXml.matchAll(/<stage>([\s\S]*?)<\/stage>/gi)];
if (!stageMatches.length) return [];

const lastStageXml = stageMatches[stageMatches.length - 1][1];
let stageCode = getTag(lastStageXml, 'code');
const stageDesc = getTag(lastStageXml, 'description');
const stageDate = getTag(lastStageXml, 'date');
const stageTime = getTag(lastStageXml, 'time');
const regDateStr = getTag(xmlStr, 'reg_date');

if (!stageCode) return [];

const SKIP_CODES = new Set(['4', '5', '6']);
if (SKIP_CODES.has(stageCode)) return [];

// [4] STUCK: in-transit more than 25 days
const TRANSIT_CODES = new Set(['10', '21', '103']);
if (TRANSIT_CODES.has(stageCode) && regDateStr) {
  try {
    const [d, m, y] = regDateStr.trim().split('/');
    const regD = new Date('20' + y + '-' + m.padStart(2,'0') + '-' + d.padStart(2,'0'));
    const daysSince = Math.floor((Date.now() - regD.getTime()) / 86400000);
    if (daysSince > 25) {
      const stuckKey = tracking + '_stuck';
      if (staticData[stuckKey]) return [];
      staticData[stuckKey] = true;
      stageCode = 'STUCK';
    }
  } catch(e) {}
}

// [3] ONE MESSAGE PER STAGE
if (stageCode === (staticData[tracking] || null)) return [];
staticData[tracking] = stageCode;

return [{ json: {
  phone: order.phone,
  customer_name: order.customer_name,
  tracking_number: tracking,
  stage_code: stageCode,
  stage_date: stageDate,
  stage_time: stageTime
}}];

